D[782]={"^Increases your critical strike chance with all spells and abilities while in Bear, Dire Bear or Cat Form by (.-)%%%.%s*$","Aumenta em {{1}}% sua chance de acerto crítico com todos os feitiços e habilidades enquanto estiver em Forma de Urso, Forma de Urso Hediondo ou Forma de Felino."}
D[2608]={"^|cFF66DDFFLevel 10 Passive|r\nYou may now cast |cffffffffDarkslayer|r while moving%.\n\nRanged attacks and abilities now have a (.-)%% chance to shoot an additional shot, dealing (.-) Physical damage and generating (.-) Rage%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nPode lançar |cffffffffAssassino Sombrio|r enquanto se movimenta.\n\nOs ataques à distância e as habilidades agora têm {{1}}% chance de disparar um tiro adicional, causando {{2}} de dano Físico e gerando {{3}} Fúria."}
D[2610]={"^|cFF66DDFFLevel 10 Passive|r\nYour ranged auto attacks now generate Rage%.\n\nIn addition, teaches you |cffffffffHoundmaster's Whistle|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAgora seus ataques automáticos à distância geram Fúria.\n\nAlém disso, ensina |cffffffffApito do Mestre dos Sabujos|r."}
D[2665]={"^|cFF66DDFFLevel 10 Passive|r\nConsuming |cFFFFFFFFSoul Infusion|r now reduces the cooldown of |cFFFFFFFFTormented Souls|r by (.-) sec%.%s*$","|cFF66DDFFNível 10 — Passivo|r\nConsumir |cFFFFFFFFInfusão de Alma|r agora reduz em {{1}} s a recarga de |cFFFFFFFFAlmas Atormentadas|r."}
D[3366]={"^Increases your spell critical strike chance by (.-)%%%.%s*$","Aumenta em {{1}}% sua chance de acerto crítico com feitiços."}
D[3855]={"^Casting |cFFFFFFFFHeartseeking Bolt|r now increases your Physical damage dealt by (.-)%% for (.-)%.%s*$","Lançar |cFFFFFFFFSeta Busca-Corações|r agora aumenta seu dano Físico causado em {{1}}% durante {{2}}."}
D[3856]={"^Striking at least 5 enemies with |cffffffffDarkflock|r now causes you to unleash a flock of crows around each enemy struck, dealing (.-) Twilight Damage over (.-)%.%s*$","Atingir pelo menos 5 inimigos com |cffffffffBando Sombrio|r faz você liberar um bando de corvos ao redor de cada inimigo atingido, causando {{1}} de dano Crepuscular ao longo de {{2}}."}
D[3857]={"^While |cffffffffPurity|r is active melee attacks apply |cffffffffSensed Evil|r, while |cffffffffWickedness|r is active melee attacks consume |cffffffffSensed Evil|r to deal Fire Damage%.\n\nTeaches |cffffffffDusk Blade|r%.%s*$","Enquanto que |cffffffffPureza|r está ativa, os ataques de corpo a corpo aplicam |cffffffffMal Detectado|r. Enquanto que |cffffffffMalícia|r está ativa, os ataques de corpo a corpo consomem |cffffffffMal Detectado|r para causar dano de Fogo.\n\nEntende |cffffffffLâmina do Crepúsculo|r."}
D[3874]={"^Curse an enemy, dealing (.-) Shadow Damage every (.-) sec for (.-), healing for half the damage dealt%.\n\nWhile active, the target takes (.-)%% increased damage from your |cffffffffShadow Hound|r's |cffffffffTrack|r and |cffffffffShadow Claw|r abilities%.\n\n|cFFFFFFFFFlintlock Shot|r  extends the duration of this effect by (.-) sec%.%s*$","Amaldiçoa um inimigo, causando {{1}} de dano de Sombra a cada {{2}} s durante {{3}} e curando você em metade do dano causado.\n\nEnquanto estiver ativo, o alvo recebe {{4}}% a mais de dano das habilidades |cffffffffRastrear|r e |cffffffffPata de Sombra|r do seu |cffffffffCão das Sombras|r.\n\n|cFFFFFFFFDisparo de Pistola|r estende a duração deste efeito em {{5}} s."}
D[3875]={"^Curse an enemy, dealing (.-) Shadow Damage every (.-) sec for (.-), healing for half the damage dealt%.\n\n|cFFFFFFFFFlintlock Shot|r  extends the duration of this effect by (.-) sec%.%s*$","Amaldiçoa um inimigo, causando {{1}} de dano de Sombra a cada {{2}} s durante {{3}} e curando a metade do dano causado.\n\n|cFFFFFFFFDisparo de Pistola|r estende a duração deste efeito em {{4}} s."}
D[3882]={"^Increases your dodge chance by (.-)%% for (.-), healing you for (.-) every (.-) sec%.%s*$","Aumenta sua chance de esquiva em {{1}}% durante {{2}}, curando você em {{3}} a cada {{4}} s."}
D[3885]={"^Feast on the darkness that surrounds you, healing yourself for (.-)%.%s*$","Devora a escuridão ao seu redor, curando você em {{1}}."}
D[3886]={"^Throw a bola at an enemy, dealing (.-) Physical damage and slowing their movement speed by (.-)%% for (.-)%.%s*$","Lança uma bola o inimigo, causando {{1}} de dano Físico e reduz sua velocidade de movimento em {{2}}% durante {{3}}."}
D[3887]={"^Embrace the darkness inside you, instantly generating (.-)%% maximum mana and (.-)%% maximum Rage%.%s*$","Abraça a escuridão que há dentro de você, gerando instantaneamente {{1}}% da mana máxima e {{2}}% dá Fúria máxima."}
D[3889]={"^Increases the damage of |cFFFFFFFFDarkslayer|r by (.-)%% and reduces its cost by (.-)%%%.%s*$","Aumenta o dano de |cFFFFFFFFAssassino Sombrio|r em {{1}}% e reduz seu custo em {{2}}%."}
D[3890]={"^Periodic damage dealt now has a (.-)%% chance to increase your Shadow damage dealt against the target by (.-)%% for (.-)%.%s*$","O dano periódico que se causa agora tem {{1}}% de chance de aumentar seu dano com Sombras contra o alvo em {{2}}% durante {{3}}."}
