D[76304]={"^|cffffffffFlintlock Shot|r, |cffffffffWitchbane|r, and |cffffffffNoctis Blade|r now increase Magic Damage you deal to an enemy by (.-)%% and allows you to see them while stealthed for (.-)%.%s*$","|cffffffffTiro de Pederneira|r, |cffffffffRuína das Bruxas|r e |cffffffffLâmina de Noctis|r agora aumentam em {{1}}% o dano Mágico que você causa a um inimigo e permitem enxergá-lo enquanto estiver em Furtividade durante {{2}}."}
D[76305]={"^|cffffffffFlintlock Shot|r, |cffffffffWitchbane|r, and |cffffffffDusk Blade|r now increase Magic Damage you deal to an enemy by (.-)%% and allows you to see them while stealthed for (.-)%.%s*$","|cffffffffTiro de Pederneira|r, |cffffffffRuína das Bruxas|r e |cffffffffLâmina do Crepúsculo|r agora aumentam em {{1}}% o dano Mágico que você causa a um inimigo e permitem enxergá-lo enquanto estiver em Furtividade durante {{2}}."}
D[76462]={"^Increases the damage of |cffffffffShadow Rage|r by 20%% of your ranged attack power%.%s*$","Aumenta o dano de |cffffffffFúria Sombria|r em 20% de seu poder de ataque à distância."}
D[76587]={"^Ranged ability damage now has a (.-)%% chance to allow the use of Witchbane while moving and increase its damage dealt and Rage cost by 20%% for (.-)%.%s*$","O dano de habilidades à distância agora tem {{1}}% de chance de permitir o uso de Ruína das Bruxas em movimento e aumentar em 20% o dano causado e o custo de Raiva durante {{2}}."}
D[76661]={"^|cffffffffMaximum Ammunition: 8|r\nEquip your |cffffffffStandard Rounds|r and instantly |cffffffffReload|r%.\n\nWhile equipped, |cFFFFFFFFScrap Shot|r shoots a |cFFFFFFFFStandard Round|r%.%s*$","|cffffffffMunição Máxima: 8|r\nEquipe suas |cffffffffBalas Padrão|r e use |cffffffffRecarregar|r instantaneamente.\n\nEnquanto estiverem equipadas, |cFFFFFFFFDisparo de Sucata|r dispara uma |cFFFFFFFFBala Padrão|r."}
D[76715]={"^Fire several bullets, striking up to (.-) enemies for (.-)%% Weapon Damage plus (.-) as Shadow Damage%.\n\nGrants |cffffffffBlasting Powder|r for (.-)%.%s*$","Dispara várias balas, golpeando até {{1}} inimigos em {{2}}% do dano da arma mais {{3}} como dano de Sombra.\n\nConcede |cffffffffPólvora Explosiva|r para {{4}}."}
D[76716]={"^Fire several bullets, striking up to (.-) enemies for (.-)%% Weapon Damage plus (.-) as Shadow Damage%.%s*$","Dispara várias balas, golpeando até {{1}} inimigos em {{2}}% do dano da arma mais {{3}} como dano de Sombra."}
D[76842]={"^|cffffffffBloodfang Bite|r and |cffffffffAtherann's Anguish|r now increases the damage of |cffffffffFinger of Agony|r by (.-)%%, stacking (.-) times, for (.-)%.%s*$","|cffffffffMordida da Presa de Sangue|r e |cffffffffAngústia de Atherann|r agora aumentam o dano de |cffffffffDedo do Dor|r em {{1}}%, acumulando-se {{2}} vezes, durante {{3}}."}
