T[9987]={"^Causes (.-) Shadow Damage every (.-) sec%. Damage Taken from Houndmaster's Call increased by (.-)%%%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s. O dano recebido por Chamado do Mestre dos Sabujos aumenta em {{3}}%."}
T[10092]={"^(.-)%% of magic damage taken is redirected to the Witching Beast%.%s*$","O {{1}}% do dano mágico recebido é redirecionado à Fera de Bruxaria."}
T[10245]={"^Causes critical strikes while |cffffffffWitchblast Musket|r is active to grant your pet |cffffffffScent of Magic|r for (.-), increasing its movement speed, and increasing the damage of its next |cffffffffTrack|r%. Stacks (.-) times%.%s*$","Acertos críticos enquanto |cffffffffMosquete da Bruxa|r estiver ativo concedem ao seu mascote |cffffffffOlfato Mágico|r durante {{1}}, aumentando a velocidade de movimento dele e o dano da próxima habilidade |cffffffffRastrear|r. Acumula até {{2}} vezes."}
T[10315]={"^Damage of next Glorious Execution increased by (.-)%%%.%s*$","O dano da próxima Execução Gloriosa aumenta em {{1}}%."}
T[10604]={"^Causes (.-) Shadow Damage every (.-) sec%. Damage Taken from Houndmaster's Call increased by (.-)%%%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s. O dano recebido por Chamado do Mestre dos Sabujos aumenta em {{3}}%."}
T[10747]={"^Movement Speed increased by (.-)%%%. At the end of this effect, you automatically Reload%.%s*$","A velocidade de movimento aumenta em {{1}}%. Quando termina este efeito, te recargas automaticamente."}
T[10933]={"^You're in your Mechsuit and you're READY TO GO!\n\nIncreases all damage dealt by (.-)%%, , reducing all damage taken by (.-)%%, and transforms |cffffffffScrap Shot|r and |cffffffffReload|r into |cffffffffMechsuit|r abilities%.\n\nCannot generate |cffc7c7c7Scrap|r and movement speed cannot be reduced below 90%% of normal speed while active%.%s*$","Você está em seu Traje Mecânico e PRONTO PARA A AÇÃO!\n\nAumenta em {{1}}% todo o dano causado, reduz em {{2}}% todo o dano recebido e transforma |cffffffffDisparo de Sucata|r e |cffffffffRecarregar|r em habilidades do |cffffffffTraje Mecânico|r.\n\nEnquanto estiver ativo, você não pode gerar |cffc7c7c7Sucata|r e sua velocidade de movimento não pode ser reduzida abaixo de 90% do normal."}
T[10934]={"^You're in your Mechsuit and you're READY TO GO!\n\nIncreases all damage dealt by (.-)%%,  and transforms |cffffffffScrap Shot|r and |cffffffffReload|r into |cffffffffMechsuit|r abilities%.\n\nCannot generate |cffc7c7c7Scrap|r and movement speed cannot be reduced below 90%% of normal speed while active%.%s*$","Você está em seu Traje Mecânico e PRONTO PARA A AÇÃO!\n\nAumenta em {{1}}% todo o dano causado e transforma |cffffffffDisparo de Sucata|r e |cffffffffRecarregar|r em habilidades do |cffffffffTraje Mecânico|r.\n\nEnquanto estiver ativo, você não pode gerar |cffc7c7c7Sucata|r e sua velocidade de movimento não pode ser reduzida abaixo de 90% do normal."}
T[11007]={"^Your next Quickdraw ignores Armor%.%s*$","Seu próximo Saque Rápido ignora a Armadura."}
T[11165]={"^You are using your Sniper Rifle%.\n\nYour Scrap Shots will have a (.-)%% reduced Firing Rate, but will ignore (.-)%% of your target's Armor, and have (.-)%% increased Critical Strike Damage%. If you are at least 10 yards away from your target, your Scrap Shots will also increase your Critical Strike Rating by (.-)%% of your Intellect for (.-)%.%s*$","Você está usando seu Fuzil de Precisão.\n\nSeus Disparos de Sucata têm a cadência de tiro reduzida em {{1}}%, mas ignoram {{2}}% da Armadura do alvo e recebem {{3}}% de bônus no dano crítico. Se você estiver a pelo menos 10 m do alvo, seus Disparos de Sucata também aumentam sua índice de acerto crítico em {{4}}% do seu Intelecto durante {{5}}."}
T[11177]={"^You are using your Shotgun%.\n\nScrap Shot has reduced range and deals less damage, but has increased Critical Strike chance and hits multiple enemies in a small cone%.%s*$","Você está usando sua Espingarda.\n\nDisparo de Sucata tem alcance reduzido e causa menos dano, mas possui maior chance de acerto crítico e atinge vários inimigos em um pequeno cone."}
T[11202]={"^The Witch Hunter can not gain a stack of Dark Penance from this unit%.%s*$","O Caçador de Bruxas não pode obter um acúmulo de Penitência Sombria a partir desta unidade."}
T[11221]={"^Melee Attack Speed increased by (.-)%%%.%s*$","Aumenta a velocidade de ataque corpo a corpo em {{1}}%."}
T[11294]={"^You take (.-)%% increased damage from the Witch Hunter%.%s*$","Recebe um aumento de dano de {{1}}% por parte do Caçador de Bruxas."}
T[11482]={"^The Witch Hunter has (.-)%% increased critical strike chance with Magic spells and abilities against this target%.%s*$","O Caçador de Bruxas tem {{1}}% a mais de chance de acerto crítico com feitiços e habilidades mágicas contra este alvo."}
T[11495]={"^The Witch Hunter has (.-)%% increased critical strike chance with Magic spells and abilities against this target%.%s*$","O Caçador de Bruxas tem {{1}}% a mais de chance de acerto crítico com feitiços e habilidades mágicas contra este alvo."}
T[11541]={"^Wails with anguish, inflicting Shadow damage to an enemy%.%s*$","Solta um lamento angustiado, causando dano de Sombra a um inimigo."}
T[11542]={"^Increases damage taken by Baroness by (.-)%% but damage dealt to Baroness increased by (.-)%%%.%s*$","Aumenta o dano recebido pela Baronesa em {{1}}% mas aumenta o dano causado à Baronesa em {{2}}%."}
T[11628]={"^Causes Fire Damage when consumed by the Witch Hunter%.%s*$","Causa dano de Fogo quando é consumido pelo Caçador de Bruxas."}
T[13287]={"^Causing a |cffFF9900Mythical Barrier|r to surround around all party members dealing damage to all nearby enemies lasting for |cffFF9900(.-)|r%.%s*$","Faz com que um |cffFF9900Escudo Mítico|r envolva todos membros do grupo, causando dano a todos os inimigos próximos durante |cffFF9900{{1}}|r."}
T[13870]={"^|cffffffffShadowblast|r and |cFFFFFFFFShadow Shot|r now grant |cffffffffBlasting Powder|r for (.-)%.%s*$","|cffffffffRajada Sombria|r e |cFFFFFFFFTiro Sombrio|r agora concedem |cffffffffPólvora Explosiva|r para {{1}}."}
T[14025]={"^Causes critical strikes from |cffffffffShadowblast|r and |cffffffffSaber Slash|r to reduce the cooldown of |cffffffffHoundmaster's Call|r by (.-) sec and |cffffffffFlourish|r by (.-) sec%.%s*$","Acertos críticos de |cffffffffRajada Sombria|r e |cffffffffTalhada de Sabre|r reduzem em {{1}} s a recarga de |cffffffffChamado do Mestre dos Sabujos|r e em {{2}} s a recarga de |cffffffffFlorescer|r."}
T[14291]={"^Causes (.-) Shadow damage every (.-) sec%.\n\nTakes increased damage from the Shadow Claw and Track abilities used by the Witch Hunter's hound%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} segundos.\n\nRecebe dano aumentado de Garra Sombria e Rastrear, usados pelo cão do Caçador de Bruxas."}
T[14292]={"^Causes (.-) Shadow damage every (.-) sec%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s."}
T[14398]={"^Maximum ammunition is 4%. |cFFFFFFFFBlackpowder Shot|r is now instant, has a 10 yd range, and hits enemies in a cone%.\n\n|cffffffffMaximum Ammunition: 4|r\nEquip your |cffffffffBuckshot Rounds|r and instantly |cffffffffReload|r%.\n\nWhile equipped, |cFFFFFFFFBlackpowder Shot|r has a 5 yd range and shoots a |cFFFFFFFFBuckshot Round|r%.%s*$","A munição máxima é 4. |cFFFFFFFFDisparo de Pólvora Negra|r agora é instantâneo, tem alcance de 10 m e atinge os inimigos em um cone.\n\n|cffffffffMunição máxima: 4|r\nEquipa seus |cffffffffCartuchos de Chumbo|r e usa |cffffffffRecarregar|r imediatamente.\n\nEnquanto estiverem equipados, |cFFFFFFFFDisparo de Pólvora Negra|r tem alcance de 5 m e dispara um |cFFFFFFFFCartucho de Chumbo|r."}
T[14399]={"^Maximum ammunition is 6%. Blackpowder Shots have a 1%.5 sec cast time and launch a bomb that explodes on impact with the target, dealing Fire Damage to multiple enemies%.%s*$","O máximo de munição é 6. Os Disparos de Pólvora Negra têm um tempo de lançamento de 1.5 s e lança uma bomba que explode ao impactar com o alvo, causando dano de Fogo a vários inimigos."}
T[14429]={"^Deals (.-) Shadow damage to up to 3 enemies%.%s*$","causa {{1}} de dano de Sombra até 3 inimigos."}
T[14438]={"^Increases the health costs of your spells by (.-)%%%$%?s504252%[, your critical strike chance with |cffffffffAtherann's Anguish|r by (.-)%%%]%[%] and increases their damage by (.-)%%%. Each stack also reduces damage taken from area of effect harmful effects by (.-)%%%. Stacks (.-) times%.\n\nReaching (.-) stacks makes you |cffffffffInsatiable|r, losing 30%% damage dealt every (.-) sec until |cffffffffThirst|r ends%.%s*$","Aumenta o custo de vida de seus feitiços em {{1}}%$?s504252[ e a chance de acerto crítico de |cffffffffAngústia de Atherann|r em {{2}}%][] e aumenta o dano deles em {{3}}%. Cada acúmulo também reduz em {{4}}% o dano recebido de efeitos nocivos em área. Acumula até {{5}} vezes.\n\nAo alcançar {{6}} acúmulos, você se torna |cffffffffInsaciável|r e perde 30% do dano causado a cada {{7}} s até |cffffffffSede|r terminar."}
T[14591]={"^Using |cffffffffHoundmaster's Call|r summons (.-) lesser |cffffffffShadow Hound|r that leaps at the target and deals (.-) Shadow damage%. \n\nThe lesser |cffffffffShadow Hound|r will persist for (.-)%.%s*$","Usando |cffffffffChamado do Mestre dos Sabujos|r evocar {{1}} menor |cffffffffCão Sombrio|r que salta em direção ao alvo e causa {{2}} de dano de Sombra.\n\nO menor |cffffffffCão Sombrio|r persistirá durante {{3}}."}
T[14592]={"^|cffffffffShadowblast|r grants Shadow Rage to your Shadow Hound%.%s*$","|cffffffffRajada Sombria|r concede Fúria Sombria ao seu Cão Sombrio."}
T[14605]={"^Reduces the cooldown of |cffffffffBola Shot|r by (.-) sec and |cffffffffSaber Slash|r and |cffffffffSearing Blade|r now deal (.-)%% increased damage against enemies slowed by its effect%.%s*$","Reduz a recarga de |cffffffffBola|r em {{1}} s e |cffffffffTalhada de Sabre|r e |cffffffffLâmina Ardente|r agora causam {{2}}% a mais de dano contra inimigos Desacelerados por seu efeito."}
T[14606]={"^Reduces the cooldown of |cffffffffBola Shot|r by (.-) sec and |cffffffffSaber Slash|r now deal (.-)%% increased damage against enemies slowed by its effect%.%s*$","Reduz a recarga de |cffffffffBola|r em {{1}} s e |cffffffffTalhada de Sabre|r agora causam {{2}}% a mais de dano contra inimigos Desacelerados por seu efeito."}
T[14692]={"^Increases the health costs of your spells by (.-)%%%$%?s504252%[, your critical strike chance with |cffffffffAtherann's Anguish|r by (.-)%%%]%[%] and increases their damage by (.-)%%%. Stacks (.-) times%.\n\nReaching (.-) stacks makes you |cffffffffInsatiable|r, losing 30%% damage dealt every (.-) sec until |cffffffffThirst|r ends%.%s*$","Aumenta o custo de vida de seus feitiços em {{1}}%$?s504252[ e a chance de acerto crítico de |cffffffffAngústia de Atherann|r em {{2}}%][] e aumenta o dano deles em {{3}}%. Acumula até {{4}} vezes.\n\nAo alcançar {{5}} acúmulos, você se torna |cffffffffInsaciável|r e perde 30% do dano causado a cada {{6}} s até |cffffffffSede|r terminar."}
T[14812]={"^Maximum ammunition is 4%. |cFFFFFFFFBlackpowder Shot|r is now instant, has a 10 yd range, and hits enemies in a cone%.%s*$","Munição máxima: 4. |cFFFFFFFFDisparo de Pólvora Negra|r agora é instantâneo, tem alcance de 10 m e atinge inimigos em um cone."}
T[14813]={"^Maximum ammunition is 8%. |cffffffffBlackpowder Shot|r has a 30 yd range and 1 sec cast time%.%s*$","Munição máxima: 8. |cffffffffDisparo de Pólvora Negra|r tem alcance de 30 m e tempo de lançamento de 1 s."}
T[14820]={"^Attacks from your turrets now generate 1%% Scrap for you, and you generate an additional 1%% Scrap whenever you Reload%.%s*$","Ataques de seus torretas agora geram 1% de Resíduos para você, e gera um adicional de 1% de Resíduos sempre que Recargas."}
T[14821]={"^Damage of Blackpowder Shot increased by (.-)%%%. Movement speed increased by (.-)%%%.\n\nReloading 1 Standard Ammunition every (.-) sec%.%s*$","Dano de disparo de pólvora Negra aumenta em {{1}}%. Velocidade de movimento aumentada em {{2}}%.\n\nRecarrega 1 Munição Estandar a cada {{3}} s."}
T[14880]={"^The Witch Hunter has (.-)%% increased ranged and melee critical strike chance against you%. All attackers have their attack powder increased by 150 against you%.%s*$","O Caçador de Bruxas tem um aumento do {{1}}% na chance de acerto crítico à distância e corpo a corpo contra você. Todos atacantes têm seu poder de ataque aumentado em 150 contra você."}
T[14886]={"^|cFFFFFFFFQuickdraw|r increases haste of the next 5 ranged attacks within (.-) by (.-)%%%.%s*$","|cFFFFFFFFSaque Rápido|r aumenta a aceleração dos próximos 5 ataques à distância em um raio de {{1}} em {{2}}%."}
T[14887]={"^Attacks have a chance to deal additional Shadow Damage%.%s*$","Os ataques têm uma chance de causar dano de Sombra adicional."}
T[15571]={"^Decimates all nearby enemies and Zombie Chows health, reducing it by half%.%s*$","Desmantela todos os inimigos próximos e reduz a vida do Zombie Chow à metade."}
T[15572]={"^Inflicts half of the targets current health as Nature damage%.\n\nDamage inflicted by Decimate can't be reduced or increased but can be prevented%.%s*$","Causa a metade da vida atual do alvo como dano de Natureza.\n\nO dano causado por Desmantelar não pode ser reduzidos nem aumentou, mas sim pode prevenir-se."}
T[16011]={"^Gluth entered a feeding frenzy after casting Decimate causing him to devour nearby Zombie Chows without a cooldown%. \n\nWhile the Feeding Frenzy lasts, all Zombie Chow's constantly walk towards Gluth to sate his hunger%.%s*$","Gluth entra em um frenesi alimentar após lançar Dizimar, fazendo com que devore os Zumbis de Ração próximos sem tempo de recarga.\n\nEnquanto durar o Frenesi Alimentar, todos os Zumbis de Ração caminham constantemente em direção a Gluth para saciar sua fome."}
T[17105]={"^Pyroclasmic Reload Living Bomb refresh%s*$","Recarga pirolímite (recarga de Bomba viva)"}
T[17758]={"^Tracking how many evil%-doers have been slain%.\n\nEach stack is 1 evil%-doer dealt with%. Huzzah!%s*$","Rastreando quantos malfeitores foram derrotados.\n\nCada acúmulo é um 1 malfeitor removido. Hurra!"}
T[18528]={"^At 5 stacks your Quickdraw is transformed into Sixfold Shot%.%s*$","Com 5 acúmulos, sua velocidade de disparo transforma-se em disparo múltiplo."}
T[18545]={"^Attacks made by the Witch Hunter against this target grant them Flames of Sin and increase the duration by 2 sec%.%s*$","Os ataques realizados pelo Cazahuerfanos contra este alvo lhes concede Chamas do pecado e aumenta a duração em 2 s."}
T[18657]={"^Maximum ammunition is 8%. |cffffffffScrap Shot|r has a 30 yd range and 1 sec cast time%.%s*$","Munição máxima: 8. |cffffffffDisparo de Sucata|r tem alcance de 30 m e tempo de lançamento de 1 s."}
